        cache.put(storeId, sku, live);
        return live;
    }

    private StockBadge cachedBadge(String storeId, String sku, Throwable cause) {
        return cache.get(storeId, sku).map(StockBadge::stale).orElse(StockBadge.HIDDEN);   // never "in stock" by default
    }
